INSERT INTO `score_predictions` (`id`, `user_id`, `predicted_marks`, `predicted_air_band`, `payload`, `created_at`) VALUES
('5b99b85a-6f2b-4b48-a53b-e78b7fd2d252','249d0aa8-37fa-4367-8792-b304afea8457',20,'700000-800000','{"advice": ["Focus on understanding fundamental concepts thoroughly before attempting too many questions.", "Prioritize accuracy over the number of questions attempted.", "Review incorrect answers to identify patterns and areas needing improvement.", "Consider working through NCERT textbooks diligently for a strong foundation."], "strengths": ["Persistence in attempting tests"], "weaknesses": ["Very low accuracy across all attempts", "Struggling with basic concepts, leading to negative marking", "Difficulty converting attempts into correct answers"], "predicted_marks": 20, "subject_breakdown": [], "predicted_air_band": "700000-800000"}','2026-06-07 11:45:33.880951'),
('a574fd3b-88c8-4e20-b691-d3286800c06e','249d0aa8-37fa-4367-8792-b304afea8457',20,'7,00,000+','{"advice": ["Focus on understanding the basic concepts thoroughly before moving to complex topics.", "Practice more to improve accuracy and reduce negative marking.", "Work on time management skills to attempt more questions in the given time."], "strengths": [], "weaknesses": ["Fundamental concepts across all subjects", "Accuracy in answering questions", "Time management during tests"], "predicted_marks": 20, "subject_breakdown": [], "predicted_air_band": "7,00,000+"}','2026-06-08 14:52:39.881023'),
('3f4bc0b3-011b-4a2f-a8c1-d7f248c7bdfd','249d0aa8-37fa-4367-8792-b304afea8457',20,'7,00,000+','{"advice": ["Focus on foundational concepts: Start with the absolute basics in all subjects to build a strong understanding.", "Prioritize accuracy over attempts: Instead of attempting many questions and getting them wrong, focus on accurately answering fewer questions.", "Understand the NEET-UG scoring pattern: Learn about positive and negative marking to strategize attempts better.", "Analyze mistakes thoroughly: For every incorrect answer, understand why it was wrong and rectify the concept.", "Seek personalized guidance: A mentor or tutor can help identify specific learning gaps and provide tailored support.", "Develop a structured study plan: A consistent daily study routine covering all subjects is crucial.", "Practice with solved examples: Work through solved problems to understand application of concepts."], "strengths": ["Persistence: The student has attempted 20 tests, showing a commitment to practice."], "weaknesses": ["Very low average score: An average score of 4% is extremely low, indicating a fundamental lack of understanding or frequent incorrect answers.", "Inconsistent performance: Scores fluctuate wildly, from -5 to 30, suggesting a lack of consistent preparation or understanding.", "High number of incorrect answers: In almost all recent attempts, the number of wrong answers is high, resulting in negative marking.", "Lack of obvious subject-specific strengths: Without subject-wise data, it\'s impossible to identify any areas of relative strength."], "predicted_marks": 20, "subject_breakdown": [], "predicted_air_band": "7,00,000+"}','2026-06-09 16:11:04.901124'),
('7437631c-bc03-4985-acaf-5194c7d3cd64','9926f000-31be-4fd6-8c1a-dd07d8973b47',300,'50000-100000','{"advice": ["Focus on strengthening foundational concepts across all subjects.", "Practice a wide variety of problems to improve application skills.", "Work on time management strategies during tests.", "Analyze mistakes to identify recurring errors and address conceptual gaps."], "strengths": ["Basic understanding of concepts in most subjects."], "weaknesses": ["Lack of in-depth knowledge and application skills.", "Time management in competitive settings.", "Accuracy in answering questions."], "predicted_marks": 300, "subject_breakdown": [{"subject": "Physics", "max_marks": 180, "predicted_marks": 70}, {"subject": "Chemistry", "max_marks": 180, "predicted_marks": 80}, {"subject": "Biology", "max_marks": 360, "predicted_marks": 150}], "predicted_air_band": "50000-100000"}','2026-06-09 19:27:48.334078'),
('75d81471-5c58-4396-b17c-2421d43618f6','249d0aa8-37fa-4367-8792-b304afea8457',50,'7,00,000 - 8,00,000','{"advice": ["Focus on understanding fundamental concepts thoroughly before attempting to solve problems.", "Prioritize accuracy over the number of questions attempted. It\'s better to answer fewer questions correctly than many incorrectly.", "Work on improving conceptual clarity in all subjects, rather than just memorizing facts.", "Implement a daily study schedule that allocates dedicated time for each subject, focusing on active learning and problem-solving.", "Regularly review mistakes to identify patterns and areas that need more attention.", "Consider seeking guidance from teachers or tutors to clarify difficult topics."], "strengths": ["Persistence in attempting tests"], "weaknesses": ["Very low accuracy in answering questions", "Struggles with basic concepts across all subjects", "Significant negative marking indicating guessing or fundamental misunderstandings"], "predicted_marks": 50, "subject_breakdown": [], "predicted_air_band": "7,00,000 - 8,00,000"}','2026-06-10 10:42:06.701518'),
('d701289c-e4bc-483d-b1eb-2b1f962458f5','249d0aa8-37fa-4367-8792-b304afea8457',20,'7,00,000 - 10,00,000','{"advice": ["Focus on understanding fundamental concepts thoroughly before attempting too many problems.", "Prioritize accuracy over the number of questions attempted. It\'s better to get a few questions correct than many wrong.", "Review incorrect answers diligently to identify patterns and areas of misunderstanding.", "Consider seeking guidance from teachers or mentors to clarify difficult topics.", "Develop a structured study plan that covers all subjects systematically.", "Practice with untimed quizzes to build confidence and accuracy without pressure."], "strengths": ["Persistence: You have attempted 21 tests, showing a commitment to practice."], "weaknesses": ["Very low accuracy across all test types.", "Struggling with basic concepts, leading to negative scores.", "High number of incorrect answers.", "Inconsistent performance, with scores ranging from negative to low positives."], "predicted_marks": 20, "subject_breakdown": [], "predicted_air_band": "7,00,000 - 10,00,000"}','2026-06-10 14:23:51.765548'),
('6fbcb6bc-e49b-4468-a4c1-a50f71494f0c','e3a4625a-0ee7-4394-8c17-ab6242e09a07',120,'700000-1000000','{"advice": ["Focus on understanding fundamental concepts thoroughly in Physics and Chemistry. Do not move to advanced topics without mastering basics.", "Practice a wide variety of questions, even if you are confident in a topic. This will ensure sufficient coverage of question types.", "Identify and work on specific topics within Physics and Chemistry where mistakes are most frequent.", "Implement a consistent study schedule that includes dedicated time for each subject. Maintain this schedule regularly.", "Review incorrect answers from past tests to understand the reasons behind mistakes (conceptual error, silly mistake, speed issue).", "Improve time management during tests by practicing with a timer.", "Consider attempting more daily tests to build consistency before moving to larger contest-style tests."], "strengths": ["Ability to answer some Physics and Chemistry questions correctly even if accuracy is low.", "Successfully solves some Biology questions and makes fewer mistakes in this subject."], "weaknesses": ["Very low overall accuracy in both Physics and Chemistry.", "Struggles with time management, leading to unanswered questions or rushed attempts.", "Inconsistent performance in different test types (contest vs. daily).", "High number of incorrect answers in past attempts, suggesting conceptual gaps."], "predicted_marks": 120, "subject_breakdown": [{"subject": "Physics", "max_marks": 180, "predicted_marks": 30}, {"subject": "Chemistry", "max_marks": 180, "predicted_marks": 30}, {"subject": "Biology", "max_marks": 360, "predicted_marks": 60}], "predicted_air_band": "700000-1000000"}','2026-06-11 05:04:22.590782'),
('89777793-9fd5-4c95-8bb0-8cd8daf91146','249d0aa8-37fa-4367-8792-b304afea8457',85,'AIR 700,000 - 900,000','{"advice": ["Stop Guessing Immediately: Your overall accuracy is ~32%, leading to significant negative marks. For the next 5 mock tests, only answer questions where you are more than 80% confident. This will train you to avoid penalties.", "Master the Basics: An accuracy of only 28% on \\"easy\\" questions is a critical issue. Pause advanced problem-solving and spend the next 3 weeks re-reading NCERT textbooks for your weakest chapters, like \\"Chemical Bonding\\" and \\"Motion in a Plane\\".", "Implement the 3-Round Strategy: In every test, go through the paper in 3 rounds. Round 1 (45 mins): Solve only the easiest, direct-formula/fact questions. Round 2 (90 mins): Solve questions that require some calculation. Round 3 (45 mins): Attempt the toughest questions. This will maximize your score on questions you know.", "Focus on Biology First: Biology is your highest-scoring area (35% accuracy). Focus on increasing this to at least 60% in the next month. Solve 40+ PYQs from chapters like \\"Cell Cycle\\" and \\"Biological Classification\\" daily.", "Reduce Test Frequency: You have taken 42 tests. More tests are not the answer. Switch to one full mock test every 2 weeks. Spend the 13 days in between on intensive chapter-wise study and practice based on the analysis of that single test."], "strengths": ["Photosynthesis in Higher Plants (75% accuracy)", "Breathing and Exchange of Gases (56% accuracy)", "Plant Kingdom (50% accuracy)"], "confidence": "high", "weaknesses": ["Chemical Bonding and Molecular Structure (21% accuracy)", "Motion in a Plane (21% accuracy)", "Cell Cycle and Cell Division (26% accuracy)", "Extremely low accuracy (28%) on easy questions"], "predicted_marks": 85, "subject_breakdown": [{"subject": "Biology", "max_marks": 360, "predicted_marks": 43}, {"subject": "Chemistry", "max_marks": 180, "predicted_marks": 24}, {"subject": "Physics", "max_marks": 180, "predicted_marks": 18}], "predicted_air_band": "AIR 700,000 - 900,000"}','2026-07-01 16:13:49.591004'),
('4e41f916-687c-4042-b282-d9b57a0309af','249d0aa8-37fa-4367-8792-b304afea8457',25,'Not Qualified','{"advice": ["Stop taking full-length mock tests. Your current scores indicate they are not an effective learning tool for you right now.", "Return to NCERT textbooks immediately. Focus on understanding core concepts from scratch, one chapter at a time, before attempting any questions.", "For the next 3 weeks, target completing 3-4 chapters from Biology. Read the chapter thoroughly and then try to solve at least 40-50 basic questions from that chapter, aiming for 60% accuracy.", "Do not focus on speed. Your initial goal is to understand the material and answer correctly, no matter how long it takes.", "Given the extremely low scores after 44 attempts, you must seek help. Consider hiring a tutor or joining a foundational course to rebuild your concepts from the ground up.", "Only resume practice tests after you can consistently score above 60% in individual chapter tests for at least 5-6 chapters."], "strengths": ["None identified"], "confidence": "high", "weaknesses": ["Fundamental conceptual gaps across all subjects. Performance data indicates a lack of basic knowledge in almost all chapters."], "predicted_marks": 25, "subject_breakdown": [{"subject": "Physics", "max_marks": 180, "predicted_marks": 5}, {"subject": "Chemistry", "max_marks": 180, "predicted_marks": 5}, {"subject": "Biology", "max_marks": 360, "predicted_marks": 15}], "predicted_air_band": "Not Qualified"}','2026-07-28 03:28:53.437792');
